<?php
/** Homepage authoring workspace: real publication state, localized controls, shared data editor, composition and recoverable history inside the fixed admin theme. */
declare(strict_types=1);
use DBLESSCMS\{HomepageStore,HomepageLayout,Components,ContentContext,Plugins,Security,JsonStore};
use function DBLESSCMS\{e,asset};
/** Translate hardcoded Homepage controls; receive key/parameters, return text for contextual escaping without effects. */
$t=static fn(string $key,array $args=[]):string=>$context->language->text('homepage.'.$key,$args);
/** Resolve a private Homepage destination; receive route, return same-origin URL without mutation. */
$url=static fn(string $route):string=>$context->base.'/cms-admin/?view='.($route==='preview'?'plugin':'plugin-panel').'&plugin=homepage&route='.$route;
$repository=new HomepageStore($context->store);$site=$context->store->read('site');$template=$site['data']['template'];$manifest=$context->store->templates->get($template);$home=$context->store->read('home');$snapshot=$repository->read($template);$draft=$snapshot['data'];$clean=$repository->published($snapshot,$home);$document=$draft['document']??$home['data'];$revision=$snapshot['revision'];$csrf=Security::token();
$siteRevision=$draft!==null&&!$clean?$draft['siteRevision']:$site['revision'];$pageRevision=$draft!==null&&!$clean?$draft['pageRevision']:$home['revision'];$stale=!hash_equals($siteRevision,$site['revision'])||!hash_equals($pageRevision,$home['revision']);
$components=new Components(new ContentContext($context->store,$template,$context->base,'home'));$warnings=$components->validate($document);$sectionWarnings=HomepageLayout::warnings($manifest,$document);
$editorDocument=$document;unset($editorDocument['homepage']);$composition=$document['homepage']??['order'=>[],'hidden'=>[],'sections'=>[]];$rows=HomepageLayout::entries($manifest,$document,false);$route=$context->route;
$mediaRegistry=new Plugins($context->store);$mediaState=isset($mediaRegistry->all()['files-manager'])?$mediaRegistry->state('files-manager'):['enabled'=>false,'settings'=>[]];
?>
<div class="homepage-plugin" data-media-api="<?= e($mediaState['enabled']?$context->base.'/cms-admin/?view=plugin-api&plugin=files-manager&route=overview&operation=list&scope=public':'') ?>" data-media-root="<?= e($mediaState['settings']['uploads']['public']??'') ?>" data-base="<?= e($context->base) ?>" data-homepage-plugin data-language="<?= e(json_encode($context->language->messages(),JSON_THROW_ON_ERROR)) ?>" data-network-error="<?= e($t('network')) ?>">
<div class="notice error" role="alert" data-homepage-status hidden></div>
<?php if($stale): ?><p class="notice" role="status"><?= e($t('stale')) ?></p><?php endif; ?>
<?php if($warnings!==[]): ?><p class="notice" role="status"><?= e($t('componentsWarning',['items'=>implode(', ',$warnings)])) ?></p><?php endif; ?>
<?php if($sectionWarnings!==[]): ?><p class="notice" role="status"><?= e($t('unsupported',['items'=>implode(', ',$sectionWarnings)])) ?></p><?php endif; ?>
<?php if($route==='overview'): ?>
<div class="homepage-summary"><section class="panel"><h2><?= e($t('published')) ?></h2><p><?= e($home['data']['meta']['title']) ?></p><p class="muted"><?= e($t('template').': '.$manifest['name']) ?></p><small><?= e($t('revision').': '.substr($home['revision'],0,12)) ?></small></section><section class="panel"><h2><?= e($t('draft')) ?></h2><p><?= e($t($draft===null?'noDraft':($clean?'clean':'draftSaved'))) ?></p><div class="homepage-actions"><a class="button-primary" href="<?= e($url('editor')) ?>"><?= e($t('edit')) ?></a><?php if($draft!==null): ?><a class="button-secondary" target="_blank" rel="noopener" href="<?= e($url('preview')) ?>"><?= e($t('preview')) ?></a><?php endif; ?>

</div></section></div>
<?php if($draft!==null&&!$clean): ?><form method="post" action="<?= e($context->url('publish')) ?>" data-homepage-form data-confirm="<?= e($t('confirmPublish')) ?>"><input type="hidden" name="csrf_token" value="<?= e($csrf) ?>"><input type="hidden" name="revision" value="<?= e($revision) ?>"><button class="button-primary" type="submit" <?= $stale?'disabled':'' ?>><?= e($t('publish')) ?></button></form><?php endif; ?>
<section class="panel"><h2><?= e($t('sections')) ?></h2><ul class="homepage-section-summary"><?php foreach($rows as $entry): ?><li><strong><?= e($entry['name']) ?></strong><span class="status-pill"><?= e($t($entry['required']?'required':($entry['visible']?'visible':'custom'))) ?></span></li><?php endforeach; ?></ul></section>
<?php elseif($route==='editor'): ?>
<?php if(!isset($manifest['homepage'])): ?><p class="notice" role="status"><?= e($t('legacy')) ?></p><?php endif; ?>
<form method="post" action="<?= e($context->url('save')) ?>" data-homepage-form data-homepage-editor>
<input type="hidden" name="csrf_token" value="<?= e($csrf) ?>"><input type="hidden" name="revision" value="<?= e($revision) ?>"><input type="hidden" name="site_revision" value="<?= e($siteRevision) ?>"><input type="hidden" name="page_revision" value="<?= e($pageRevision) ?>"><input type="hidden" name="composition" data-homepage-composition value="<?= e(json_encode($composition,JSON_THROW_ON_ERROR)) ?>">
<section class="panel" data-homepage-composer data-rows="<?= e(json_encode($rows,JSON_THROW_ON_ERROR)) ?>"><div class="dashboard-card-heading"><h2><?= e($t('composition')) ?></h2><button type="button" class="button-secondary" data-homepage-add><?= e($t('addSection')) ?></button></div><p class="muted"><?= e($t('bodyHelp')) ?></p><div data-homepage-rows></div></section>
<?php require $context->config->root.'/admin/components-picker.php'; ?>
<details class="panel homepage-native-editor"><summary><?= e($t('content')) ?></summary><div class="editor-toolbar"><div class="tabs" aria-label="<?= e($t('mode')) ?>"><button type="button" data-mode="fields" aria-pressed="true"><?= e($t('fields')) ?></button><button type="button" data-mode="json" aria-pressed="false"><?= e($t('json')) ?></button></div></div><div data-editor-error class="notice error" role="alert" hidden></div><div data-fields hidden></div><label data-json-label><?= e($t('json')) ?><textarea name="document" data-document data-editor-choices="<?= e(json_encode(['status'=>['published'=>$t('published')]],JSON_THROW_ON_ERROR)) ?>" spellcheck="false" rows="25"><?= e(JsonStore::encode($editorDocument)) ?></textarea></label></details>
<div class="savebar"><span class="muted"><?= e($t('previewHelp')) ?></span><button class="button-primary" type="submit"><?= e($t('save')) ?></button></div></form>
<?php if($draft!==null): ?><div class="homepage-actions"><a class="button-secondary" target="_blank" rel="noopener" href="<?= e($url('preview')) ?>"><?= e($t('preview')) ?></a></div><?php if(!$clean): ?><form method="post" action="<?= e($context->base.'/cms-admin/?view=plugin-api&plugin=homepage&route=overview&operation=publish') ?>" data-homepage-form data-confirm="<?= e($t('confirmPublish')) ?>"><input type="hidden" name="csrf_token" value="<?= e($csrf) ?>"><input type="hidden" name="revision" value="<?= e($revision) ?>"><button class="button-primary" type="submit" <?= $stale?'disabled':'' ?>><?= e($t('publish')) ?></button></form><?php endif;endif; ?>
<form method="post" action="<?= e($context->url('reset')) ?>" data-homepage-form data-confirm="<?= e($t('confirmReset')) ?>"><input type="hidden" name="csrf_token" value="<?= e($csrf) ?>"><input type="hidden" name="revision" value="<?= e($revision) ?>"><input type="hidden" name="site_revision" value="<?= e($site['revision']) ?>"><input type="hidden" name="page_revision" value="<?= e($home['revision']) ?>"><button class="button-secondary" type="submit"><?= e($t('reset')) ?></button></form>
<?php elseif($route==='history'): $history=$context->store->history('home'); ?>
<section class="panel"><?php if($history===[]): ?><p class="empty-state"><?= e($t('noHistory')) ?></p><?php endif; ?><?php foreach($history as $backup): ?><form class="history-row" method="post" action="<?= e($context->url('restore')) ?>" data-homepage-form data-confirm="<?= e($t('confirmRestore')) ?>"><span><?= e(substr($backup,0,22)) ?></span><input type="hidden" name="csrf_token" value="<?= e($csrf) ?>"><input type="hidden" name="backup" value="<?= e($backup) ?>"><input type="hidden" name="site_revision" value="<?= e($site['revision']) ?>"><input type="hidden" name="page_revision" value="<?= e($home['revision']) ?>"><button class="button-secondary" type="submit"><?= e($t('restore')) ?></button></form><?php endforeach; ?></section>
<?php endif; ?>

<?php if($route==='editor'): ?><dialog data-homepage-media aria-labelledby="homepage-media-title"><div class="dashboard-card-heading"><h2 id="homepage-media-title"><?= e($t('images')) ?></h2><button type="button" class="button-secondary" data-homepage-media-close><?= e($t('close')) ?></button></div><div class="homepage-actions"><button type="button" class="button-secondary" data-homepage-media-back><?= e($t('back')) ?></button><span data-homepage-media-path></span><a href="<?= e($context->base.'/cms-admin/?view=plugin-panel&plugin=files-manager&route=overview') ?>" target="_blank" rel="noopener"><?= e($t('manageImages')) ?></a></div><p role="status" data-homepage-media-status></p><div class="homepage-media-grid" data-homepage-media-list></div></dialog><?php endif; ?>
</div>
